import type { EnclosureConfig } from '../types/enclosure';

export function generateScadSource(config: EnclosureConfig): string {
  const effectiveThickness = config.phoneThickness + config.caseAllowance;

  return `// ==============================================================================
// PARAMETRIC 2-PART SMARTPHONE CLOCK HOUSING (STANDALONE TABLE & WALL MOUNT)
// Generated by Web Customizer: https://tumesh007.github.io/phone-wall-clock-enclosure-generator/
// Designed for Bambu Lab A1 mini (180 x 180 x 180 mm build volume) & PETG / PLA
// 100% Support-Free Printing (Main Body prints face-down, Back Cover prints flat)
// ==============================================================================

/* [Part Selector] */
// "assembly"        : Assembled standalone clock standing upright on table base
// "main_clock_body" : Part 1: Unified Front Faceplate + Body + Table Base (print face-down)
// "hex_back_cover"  : Part 2: Hexagonal Honeycomb Ventilation Back Cover (print flat)
// "bed_layout"      : Both parts arranged flat for 3D printing
part = "${config.viewMode}"; // [assembly, main_clock_body, hex_back_cover, bed_layout]

/* [Phone Exterior Dimensions (Internal Cavity)] */
phone_length         = ${config.phoneLength.toFixed(1)}; // Phone length along horizontal X axis
phone_width          = ${config.phoneWidth.toFixed(1)};  // Phone width/height along vertical Y axis
phone_thickness      = ${effectiveThickness.toFixed(1)};  // Thickness including case allowance (${config.caseAllowance.toFixed(1)} mm)
corner_radius        = ${config.cornerRadius.toFixed(1)};  // Phone body corner radius
fit_tolerance        = ${config.fitTolerance.toFixed(2)};  // Radial clearance inside cavity (0.3 - 0.5 mm)

/* [Active Screen Viewing Window] */
screen_length        = ${config.screenLength.toFixed(1)}; // Active display visible length
screen_width         = ${config.screenWidth.toFixed(1)};  // Active display visible width
screen_corner_radius = ${config.screenCornerRadius.toFixed(1)}; // Window corner radius
screen_offset_x      = ${config.screenOffsetX.toFixed(1)}; // Horizontal window offset
screen_offset_y      = ${config.screenOffsetY.toFixed(1)}; // Vertical window offset (for chin compensation)

/* [Clock Housing & Stable Base Geometry] */
wall_thickness       = ${config.wallThickness.toFixed(1)};  // Sturdy perimeter wall thickness (>= 2.4 mm)
front_bezel_thick    = ${config.frontBezelThick.toFixed(1)};  // Front faceplate bezel thickness (>= 2.4 mm)
base_depth           = ${config.baseDepth.toFixed(1)}; // Bottom foot depth for stable tabletop stance
top_depth            = ${config.topDepth.toFixed(1)};  // Top chassis depth
back_cover_thick     = ${config.backCoverThick.toFixed(1)};  // Rear closing plate thickness
screw_hole_d         = ${config.screwHoleDiameter.toFixed(1)};  // Corner M3 screw boss diameter
corner_rad_enclosure = ${Math.max(config.cornerRadius + 2.0, 8.0).toFixed(1)};

/* [Cable Port & Speakers] */
usb_cutout_width     = ${config.usbWidth.toFixed(1)};  // Width for USB-C / microUSB charging cable
usb_cutout_height    = ${config.usbHeight.toFixed(1)};   // Cutout height
usb_side             = "${config.usbSide}"; // "right", "left", or "bottom"
honeycomb_cell_r     = 4.5;   // Honeycomb cell radius
honeycomb_wall       = 1.5;   // Honeycomb cell wall thickness

/* [Quality] */
$fn = 48;

// ==============================================================================
// DERIVED INTERNAL DIMENSIONS
// ==============================================================================
cav_x = phone_length + 2 * fit_tolerance;
cav_y = phone_width + 2 * fit_tolerance;
cav_z = phone_thickness + 0.5;

outer_x = cav_x + 2 * wall_thickness;
outer_y = cav_y + 2 * wall_thickness;
chassis_depth = max(base_depth, cav_z + front_bezel_thick + back_cover_thick + 2.0);

// ==============================================================================
// TOP-LEVEL PART SELECTOR
// ==============================================================================
if (part == "main_clock_body") {
    // Print face-down flat on bed (Z=0 on front face)
    main_clock_body();
} else if (part == "hex_back_cover") {
    // Print flat on bed (Z=0)
    hex_back_cover();
} else if (part == "bed_layout") {
    bed_layout();
} else if (part == "assembly") {
    assembled_clock();
}

// ==============================================================================
// HELPER PRIMITIVES
// ==============================================================================
module rounded_rect_2d(size, r) {
    w = size[0];
    h = size[1];
    actual_r = min(r, min(w/2, h/2));
    hull() {
        translate([-w/2 + actual_r, -h/2 + actual_r]) circle(r=actual_r);
        translate([ w/2 - actual_r, -h/2 + actual_r]) circle(r=actual_r);
        translate([ w/2 - actual_r,  h/2 - actual_r]) circle(r=actual_r);
        translate([-w/2 + actual_r,  h/2 - actual_r]) circle(r=actual_r);
    }
}

module rounded_box(size, r, center=true) {
    w = size[0];
    h = size[1];
    d = size[2];
    actual_r = min(r, min(w/2, h/2));
    if (center) {
        linear_extrude(height=d, center=true)
            rounded_rect_2d([w, h], actual_r);
    } else {
        linear_extrude(height=d)
            rounded_rect_2d([w, h], actual_r);
    }
}

module keyhole_slot(depth=3.0) {
    union() {
        cylinder(d=8.0, h=depth + 0.2, center=true);
        translate([0, 7.0/2, 0])
            cube([4.0, 7.0, depth + 0.2], center=true);
        translate([0, 7.0, 0])
            cylinder(d=4.0, h=depth + 0.2, center=true);
    }
}

// ==============================================================================
// PART 1: INTEGRATED FRONT FACEPLATE + MAIN BODY + TABLE BASE
// ==============================================================================
module main_clock_body() {
    // Front face sits on Z=0, body extrudes backwards along +Z
    difference() {
        // Outer sturdy chassis with chunky table foot
        translate([0, 0, chassis_depth/2])
            rounded_box([outer_x, outer_y, chassis_depth], corner_rad_enclosure, center=true);

        // 1. Screen Viewing Window Cutout (through front face)
        translate([screen_offset_x, screen_offset_y, -0.1])
            linear_extrude(height=front_bezel_thick + 0.5)
                rounded_rect_2d([screen_length, screen_width], screen_corner_radius);

        // 2. Open-backed Phone Pocket Cavity (reaches back surface)
        translate([0, 0, front_bezel_thick])
            linear_extrude(height=chassis_depth)
                rounded_rect_2d([cav_x, cav_y], corner_radius);

        // 3. Rear Step / Shelf for Hex Back Cover (3.0mm recessed perimeter)
        translate([0, 0, chassis_depth - back_cover_thick])
            linear_extrude(height=back_cover_thick + 0.2)
                rounded_rect_2d([cav_x + 6.0, cav_y + 6.0], corner_radius + 2.0);

        // 4. Open-Rear USB-C Cable Channel (Phone with plugged cable drops straight in!)
        if (usb_side == "right") {
            translate([outer_x/2 - wall_thickness/2, 0, front_bezel_thick + cav_z/2 + (chassis_depth - front_bezel_thick)/2])
                cube([wall_thickness * 2 + 2.0, usb_cutout_width, chassis_depth], center=true);
        } else if (usb_side == "left") {
            translate([-outer_x/2 + wall_thickness/2, 0, front_bezel_thick + cav_z/2 + (chassis_depth - front_bezel_thick)/2])
                cube([wall_thickness * 2 + 2.0, usb_cutout_width, chassis_depth], center=true);
        } else {
            translate([0, -outer_y/2 + wall_thickness/2, front_bezel_thick + cav_z/2 + (chassis_depth - front_bezel_thick)/2])
                cube([usb_cutout_width, wall_thickness * 2 + 2.0, chassis_depth], center=true);
        }

        // 5. Open-Rear Bottom Loudspeaker Relief Cutouts
        for (i = [-3: -1: -6]) {
            translate([outer_x/2 - 25.0 + i*4.2, -outer_y/2 + wall_thickness/2, front_bezel_thick + 3.0 + (chassis_depth - front_bezel_thick)/2])
                cube([3.0, wall_thickness * 2 + 2.0, chassis_depth], center=true);
        }

        // 6. 4 Corner M3 Screw Boss Pilot Holes
        boss_x = cav_x/2 + 1.8;
        boss_y = cav_y/2 + 1.8;
        for (sx = [-boss_x, boss_x]) {
            for (sy = [-boss_y, boss_y]) {
                translate([sx, sy, chassis_depth - 12.0])
                    cylinder(d=screw_hole_d, h=13.0, center=false);
            }
        }
    }
}

// ==============================================================================
// PART 2: SIMPLE HEXAGONAL MESH BACK COVER
// ==============================================================================
module hex_back_cover() {
    bp_x = cav_x + 6.0 - 0.4;
    bp_y = cav_y + 6.0 - 0.4;
    bp_z = back_cover_thick;

    difference() {
        // Flat closing plate
        translate([0, 0, bp_z/2])
            rounded_box([bp_x, bp_y, bp_z], corner_radius + 1.8, center=true);

        // 1. Central Hexagonal Honeycomb Ventilation Grid
        step_x = (honeycomb_cell_r * 2 + honeycomb_wall) * cos(30);
        step_y = (honeycomb_cell_r * 2 + honeycomb_wall) * 0.75;
        grid_w = bp_x - 52.0;
        grid_h = bp_y - 24.0;

        for (hx = [-grid_w/2 : step_x : grid_w/2]) {
            for (hy = [-grid_h/2 : step_y*2 : grid_h/2]) {
                translate([hx, hy, bp_z/2])
                    rotate([0, 0, 30])
                        cylinder(r=honeycomb_cell_r, h=bp_z + 1.0, center=true, $fn=6);
                translate([hx + step_x/2, hy + step_y, bp_z/2])
                    rotate([0, 0, 30])
                        cylinder(r=honeycomb_cell_r, h=bp_z + 1.0, center=true, $fn=6);
            }
        }

        // 2. Dual Keyhole Wall Mounting Slots (spaced 80mm)
        for (kx = [-40.0, 40.0]) {
            translate([kx, 4.0, bp_z/2])
                keyhole_slot(depth=bp_z);
        }

        // 3. Dual 3M Command Strip Recessed Landing Pads
        for (cx = [-bp_x/2 + 10.0, bp_x/2 - 10.0]) {
            translate([cx, 0, bp_z - 0.6])
                rounded_box([16.0, 50.0, 1.3], 3.0, center=true);
        }

        // 4. Corner Countersunk M3 Screw Pass-Through Holes
        boss_x = cav_x/2 + 1.8;
        boss_y = cav_y/2 + 1.8;
        for (sx = [-boss_x, boss_x]) {
            for (sy = [-boss_y, boss_y]) {
                translate([sx, sy, -0.1])
                    cylinder(d=screw_hole_d + 0.4, h=bp_z + 0.2, center=false);
                translate([sx, sy, bp_z - 1.2])
                    cylinder(d1=screw_hole_d + 0.4, d2=screw_hole_d + 2.8, h=1.4, center=false);
            }
        }
    }
}

// ==============================================================================
// ASSEMBLY PREVIEW: STANDALONE DESK & WALL CLOCK
// ==============================================================================
module assembled_clock() {
    // Stands upright on flat desk base (Y=0 bottom foot on surface)
    translate([0, 0, outer_y/2]) {
        rotate([90, 0, 0]) {
            // Main Clock Body
            color("#F8FAFC") main_clock_body();

            // Hex Back Cover seated in rear shelf
            translate([0, 0, chassis_depth - back_cover_thick])
                color("#475569") hex_back_cover();

            // Mockup Phone Ghost inside pocket
            translate([0, 0, front_bezel_thick + cav_z/2])
                color([0.1, 0.1, 0.1, 0.85])
                    rounded_box([phone_length, phone_width, phone_thickness], corner_radius, center=true);
        }
    }
}

// ==============================================================================
// 3D PRINT BED LAYOUT (BAMBU LAB A1 MINI 180 x 180 mm)
// ==============================================================================
module bed_layout() {
    // Part 1: Main Clock Body printed face-down at Z=0
    main_clock_body();

    // Part 2: Hex Back Cover printed flat
    translate([0, outer_y + 10.0, 0])
        hex_back_cover();
}
`;
}
